using NUnit.Framework;

using cloud.charging.open.protocols.ISO15118.EXI.Tests.Infrastructure;
using cloud.charging.open.protocols.ISO15118_20.CommonMessages;
using cloud.charging.open.protocols.ISO15118_20.CommonMessages.Generated;

namespace cloud.charging.open.protocols.ISO15118.EXI.Tests.Interop
{
    /// <summary>
    /// Josev's ISO 15118-20 <c>CertificateInstallationReq</c> (contract provisioning), reproduced byte-exactly
    /// with Josev's own EXIficient codec from the values captured in the 2026-07-22 live probe (a Josev EVCC
    /// with <c>isCertInstallNeeded=true</c> against our SECC; see
    /// <c>docs/interop-runs/</c> and <c>tools/interop-josev/certinstall-probe.py</c>). The ~1.8 KB frame
    /// carries the signed OEM provisioning certificate chain (leaf + 2 sub-CAs, signature over "#id1" in
    /// Josev's ecdsa-sha256 form) — the largest and only cert-install message an independent stack produces.
    /// Live, our SECC failed to decode this frame ("Unknown document index 14"); this test pins the frame so
    /// the decode path is debuggable and guarded offline.
    /// </summary>
    [TestFixture]
    public class JosevCertificateInstallationReqTests
    {
        internal const string JosevCertificateInstallationReqHex =
            "";

        [Test]
        public void Josev20_CertificateInstallationReq_DecodesAndReEncodesIdentically()
        {
            var josev = HexUtil.Parse(JosevCertificateInstallationReqHex);
            var reEncoded = Iso15118_20CommonFixtures.DecodeReEncode(josev);
            Assert.That(reEncoded, Is.EqualTo(josev),
                "our codec must re-encode Josev's -20 CertificateInstallationReq to the identical bytes");
        }

        /// <summary>Josev's exact 1476-byte OEM-chain fragment (EXIficient, `to_exi(SignedCertificateChain,
        /// ISO_V20_COMMON_MSG)`) — the octets its cert-install signature digests (SHA-256 == the DigestValue
        /// inside the pinned frame above). Reproduced by tools/interop-josev/certinstall-probe.py.</summary>
        internal const string JosevOemChainFragmentHex =
            "";

        [Test]
        public void Josev20_OemChainFragment_IsByteExact_AndDigestMatchesTheSignature()
        {
            var frame = HexUtil.Parse(JosevCertificateInstallationReqHex);
            var req = (CertificateInstallationReq)CommonMessagesCodec.DecodeAny(frame, out _);

            var buf = new byte[4096];
            Assert.That(CommonMessagesCodec.EncodeFragment_OEMProvisioningCertificateChain(
                req.OEMProvisioningCertificateChain, buf, out int n), Is.True);
            Assert.That(Convert.ToHexString(buf.AsSpan(0, n)).ToLowerInvariant(), Is.EqualTo(JosevOemChainFragmentHex),
                "our OEMProvisioningCertificateChain fragment must be byte-identical to EXIficient's");

            var digest = System.Security.Cryptography.SHA256.HashData(buf.AsSpan(0, n));
            Assert.That(digest, Is.EqualTo(req.Header.Signature!.SignedInfo.Reference[0].DigestValue),
                "SHA-256 of the fragment must equal the DigestValue Josev signed");
        }

    }
}
